using Astrea.RunModifiers;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RewardLocation", menuName = "Data/Map/Reward Location")]
public class RewardLocation : Location
{
	[Header("Rewards")]
	[SerializeField]
	protected ClearingReward clearingReward;

	[SerializeField]
	private bool goldLocation;

	[SerializeField]
	private bool destroyLocation;

	[SerializeField]
	[ShowIf("destroyLocation")]
	private ClearingReward destroyOneDieClearingReward;

	public ClearingReward ClearingReward => clearingReward;

	public override NodeData GetNodeData()
	{
		if (ReferenceSingleton<RunModifiersManager>.Instance.MysteriousAdventureRunModifier != null)
		{
			NodeData nodeData = ReferenceSingleton<RunModifiersManager>.Instance.MysteriousAdventureRunModifier.GetCurrentEventLocation().GetNodeData();
			DraftDiceRunModifier draftDiceRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.DraftDiceRunModifier;
			if (goldLocation)
			{
				return nodeData;
			}
			if (clearingReward is DiceClearingReward && draftDiceRunModifier != null && draftDiceRunModifier.IsTheChosenPool)
			{
				return nodeData;
			}
		}
		return new NodeData
		{
			NodeEnum = NodeEnum.REWARD,
			Reward = GetClearingReward().name
		};
	}

	public virtual ClearingReward GetClearingReward()
	{
		DraftDiceRunModifier draftDiceRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.DraftDiceRunModifier;
		OnlySpecificChestRunModifier onlySpecificChestRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.OnlySpecificChestRunModifier;
		StellarHeritageRunModifier stellarHeritageRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.StellarHeritageRunModifier;
		if (clearingReward is DiceClearingReward)
		{
			if (draftDiceRunModifier != null && draftDiceRunModifier.IsTheChosenPool)
			{
				return draftDiceRunModifier.RewardToChangeOnMap;
			}
			if (onlySpecificChestRunModifier != null)
			{
				return onlySpecificChestRunModifier.DiceClearingReward;
			}
		}
		else if (goldLocation)
		{
			if (stellarHeritageRunModifier != null && (draftDiceRunModifier == null || (draftDiceRunModifier != null && !draftDiceRunModifier.IsTheChosenPool)))
			{
				if (onlySpecificChestRunModifier != null)
				{
					return onlySpecificChestRunModifier.DiceClearingReward;
				}
				return stellarHeritageRunModifier.DiceClearingRewards.PickRandom();
			}
		}
		else if (destroyLocation)
		{
			if (!(ReferenceSingleton<RunModifiersManager>.Instance.HarshEconomyRunModifier != null))
			{
				return clearingReward;
			}
			return destroyOneDieClearingReward;
		}
		return clearingReward;
	}
}
